// === Core Processing: Normalize, Match, Dedup, Infer Projects, Diff ===
const googleData = $('Get many tasks').all();
const notionTasksData = $('Get Notion Task List1').all();
const notionProjectsData = $('Get Notion Projects1').all();

if (!googleData || googleData.length === 0) console.log('Warning: No Google Tasks found');
if (!notionTasksData || notionTasksData.length === 0) console.log('Warning: No Notion tasks found');
if (!notionProjectsData || notionProjectsData.length === 0) console.log('Warning: No Notion projects found');

const google = googleData.map(i => i.json).filter(Boolean);
const notionTasks = notionTasksData.map(i => i.json).filter(Boolean);
const notionProjects = notionProjectsData.map(i => i.json).filter(Boolean);
const TZ = 'Europe/Dublin';
const now = new Date();
const isoDate = now.toISOString().slice(0, 10);

// --- Normalization helpers ---
function norm(s) {
  if (!s) return '';
  let t = String(s).normalize('NFKC').toLowerCase();
  t = t.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '');
  t = t.replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
  return t;
}
function toks(s) { return norm(s).split(/\s+/).filter(Boolean); }
const STOP = new Set('the a an is are was were be been have has had do does did will would shall should may might can could to of in for on with at by from as and but or not this that it its i me my we our you your'.split(' '));
function cleanToks(s) { return toks(s).filter(t => !STOP.has(t)); }
const GENERIC = new Set(['email', 'call', 'follow up', 'followup', 'admin', 'review', 'check', 'update', 'meeting', 'task', 'todo', 'reminder']);
function isWeak(n) { return n.length < 8 || GENERIC.has(n); }

// --- Notion helpers ---
function first(...v) { for (const x of v) if (x != null && `${x}`.trim()) return x; return null; }
function nTitle(p) {
  if (typeof p.Name === 'string') return p.Name;
  if (typeof p.name === 'string') return p.name;
  if (typeof p.title === 'string') return p.title;
  for (const v of Object.values(p.properties || {})) {
    if (!v) continue;
    const a = v.title || (v.type === 'title' ? v.title : null);
    if (Array.isArray(a) && a.length) return a.map(t => t.plain_text || t.text?.content || '').join('').trim();
  }
  return '';
}
function nDesc(p) {
  const props = p.properties || {};
  for (const k of ['Description', 'description', 'Notes', 'notes', 'Summary', 'Details']) {
    const v = props[k];
    if (v?.type === 'rich_text' && Array.isArray(v.rich_text))
      return v.rich_text.map(t => t.plain_text || '').join('').trim();
    if (typeof p[k] === 'string') return p[k];
  }
  return '';
}
function nStatus(p) {
  const props = p.properties || {};
  const s = props.Status || props.status;
  if (!s) return first(p.Status, p.status);
  if (s.type === 'status') return s.status?.name || null;
  if (s.type === 'select') return s.select?.name || null;
  return typeof s === 'string' ? s : null;
}
function nDue(p) {
  const props = p.properties || {};
  for (const k of ['Due', 'Due Date', 'Due date', 'Date', 'Deadline']) {
    const v = props[k];
    if (v?.type === 'date') return v.date?.start || null;
    if (v?.date?.start) return v.date.start;
    if (typeof p[k] === 'string') return p[k];
    if (p[k]?.start) return p[k].start;
  }
  return null;
}
function nRelIds(p) {
  const props = p.properties || {};
  for (const k of ['Project', 'Projects', 'project', 'projects']) {
    const v = props[k];
    if (v?.type === 'relation' && Array.isArray(v.relation)) return v.relation.map(r => r.id).filter(Boolean);
    if (Array.isArray(p[k])) return p[k].map(r => r.id || r).filter(Boolean);
  }
  for (const v of Object.values(props)) {
    if (v?.type === 'relation' && Array.isArray(v.relation)) return v.relation.map(r => r.id).filter(Boolean);
  }
  return [];
}
function isDone(s) { return s ? ['done', 'completed', 'complete', 'closed', 'cancelled', 'canceled'].includes(String(s).toLowerCase()) : false; }
function dateKey(iso) { if (!iso) return null; const d = new Date(iso); return isNaN(d) ? null : d.toISOString().slice(0, 10); }

// --- Build canonical projects ---
const projects = notionProjects.map(p => {
  const pid = p.id || p.pageId; const title = nTitle(p) || ''; const desc = nDesc(p);
  const status = nStatus(p); const tn = norm(title);
  return {
    id: `notion:${pid}`, sid: pid, title, desc, status: isDone(status) ? 'done' : (status || 'active'),
    url: p.url || null, tn, txtToks: cleanToks(title + ' ' + desc), weak: isWeak(tn)
  };
});
const pMap = new Map(); for (const p of projects) pMap.set(p.sid, p);

// --- Build canonical tasks ---
const allTasks = [];
for (const t of google) {
  const title = t.title || ''; const notes = t.notes || ''; const tn = norm(title);
  allTasks.push({
    id: `gtasks:${t.id}`, src: 'gtasks', sid: t.id, title, notes, tn,
    txtToks: cleanToks(title + ' ' + notes), weak: isWeak(tn),
    status: t.status === 'completed' ? 'completed' : 'open',
    due: dateKey(t.due), dueRaw: t.due || null,
    completedAt: t.completed || null, updatedAt: t.updated || null,
    projExplicit: [], projInferred: [], url: t.webViewLink || null
  });
}
for (const nt of notionTasks) {
  const tid = nt.id || nt.pageId; const title = nTitle(nt) || '';
  const notes = first(nt.Notes, nt.notes, nt.Description, nt.description, '') || '';
  const desc = nDesc(nt); const full = notes || desc; const status = nStatus(nt);
  const relIds = nRelIds(nt); const tn = norm(title);
  allTasks.push({
    id: `notion:${tid}`, src: 'notion', sid: tid, title, notes: full, tn,
    txtToks: cleanToks(title + ' ' + full), weak: isWeak(tn),
    status: isDone(status) ? 'completed' : (status || 'open'),
    due: dateKey(nDue(nt)), dueRaw: nDue(nt),
    completedAt: isDone(status) ? (nt.last_edited_time || null) : null,
    updatedAt: nt.last_edited_time || null,
    projExplicit: relIds.map(id => `notion:${id}`), projInferred: [], url: nt.url || null
  });
}
const openTasks = allTasks.filter(t => t.status !== 'completed' && t.status !== 'cancelled');

// --- Matching: Jaccard token similarity ---
function jaccard(a, b) {
  const sa = new Set(a); const sb = new Set(b);
  const inter = [...sa].filter(x => sb.has(x)).length;
  const union = new Set([...sa, ...sb]).size;
  return union === 0 ? 0 : inter / union;
}
function dueSim(a, b) {
  if (!a || !b) return 0;
  const da = new Date(a); const db = new Date(b);
  if (isNaN(da) || isNaN(db)) return 0;
  const delta = Math.abs((da - db) / (86400000));
  return Math.max(0, 1 - Math.min(delta, 14) / 14);
}

// Block by first 3 tokens for efficiency
function blockKey(t) { return t.txtToks.slice(0, 3).join(' '); }
const blocks = {};
for (const t of openTasks) {
  const k = blockKey(t); if (!blocks[k]) blocks[k] = []; blocks[k].push(t);
}

// Find duplicates (within + cross-source)
const matches = [];
const seen = new Set();
for (const group of Object.values(blocks)) {
  for (let i = 0; i < group.length; i++) {
    for (let j = i + 1; j < group.length; j++) {
      const a = group[i]; const b = group[j];
      const key = [a.id, b.id].sort().join('|');
      if (seen.has(key)) continue; seen.add(key);
      const titleSim = jaccard(a.txtToks, b.txtToks);
      const ds = dueSim(a.due, b.due);
      let score = 0.65 * titleSim + 0.35 * ds;
      if (a.weak || b.weak) score -= 0.08;
      score = Math.max(0, Math.min(1, score));
      let conf = 'none';
      if (score >= 0.85 && titleSim >= 0.80) conf = 'high';
      else if (score >= 0.70) conf = 'possible';
      else if (score >= 0.55) conf = 'related';
      if (conf !== 'none') {
        const crossSystem = a.src !== b.src;
        matches.push({
          aId: a.id, bId: b.id, aTitle: a.title, bTitle: b.title,
          type: crossSystem ? 'cross' : 'same', score: +score.toFixed(2), conf,
          rationale: [`title_jaccard=${titleSim.toFixed(2)}`, `due_sim=${ds.toFixed(2)}`]
        });
      }
    }
  }
}

// --- Project inference for unassigned tasks ---
const unassigned = openTasks.filter(t => t.projExplicit.length === 0);
const activeProjects = projects.filter(p => p.status !== 'done');
for (const t of unassigned) {
  if (t.txtToks.length === 0) continue;
  const scored = activeProjects.map(p => ({ pid: p.id, title: p.title, score: jaccard(t.txtToks, p.txtToks) }))
    .filter(s => s.score >= 0.25).sort((a, b) => b.score - a.score);
  if (scored.length && scored[0].score >= 0.35) {
    const margin = scored.length > 1 ? scored[0].score - scored[1].score : scored[0].score;
    if (margin >= 0.07 || scored[0].score >= 0.60)
      t.projInferred = scored.slice(0, 3).map(s => ({ pid: s.pid, title: s.title, score: +s.score.toFixed(2) }));
  }
}

// --- Diff vs yesterday (via n8n static data) ---
const staticData = $getWorkflowStaticData('global');
const yesterday = staticData.snapshot || { tasks: {}, date: null };
const todaySnap = {};
for (const t of allTasks) todaySnap[t.id] = { title: t.title, status: t.status, due: t.due };

const diff = { newTasks: [], completedTasks: [], dueChanges: [], removedTasks: [] };
for (const t of allTasks) {
  const prev = yesterday.tasks[t.id];
  if (!prev) diff.newTasks.push({ id: t.id, title: t.title, src: t.src });
  else {
    if (t.status === 'completed' && prev.status !== 'completed')
      diff.completedTasks.push({ id: t.id, title: t.title, src: t.src });
    if (t.due && prev.due && t.due !== prev.due)
      diff.dueChanges.push({ id: t.id, title: t.title, oldDue: prev.due, newDue: t.due });
  }
}
for (const [id, prev] of Object.entries(yesterday.tasks)) {
  if (!todaySnap[id]) diff.removedTasks.push({ id, title: prev.title });
}

// Save today's snapshot
staticData.snapshot = { tasks: todaySnap, date: isoDate };

// --- Categorize by urgency ---
const overdue = openTasks.filter(t => t.due && t.due < isoDate).sort((a, b) => a.due.localeCompare(b.due));
const dueToday = openTasks.filter(t => t.due === isoDate);
const dueSoon = openTasks.filter(t => { if (!t.due || t.due <= isoDate) return false; const d = new Date(t.due); const s = new Date(isoDate); return (d - s) / (86400000) <= 7; }).sort((a, b) => a.due.localeCompare(b.due));

// --- Project-centric view ---
const projView = {};
for (const t of openTasks) {
  const pids = t.projExplicit.length ? t.projExplicit : t.projInferred.map(i => i.pid);
  if (pids.length === 0) continue;
  for (const pid of pids) {
    if (!projView[pid]) {
      const p = pMap.get(pid.replace('notion:', ''));
      projView[pid] = { title: p ? p.title : pid, tasks: [] };
    }
    projView[pid].tasks.push({ id: t.id, title: t.title, due: t.due, status: t.status, inferred: t.projExplicit.length === 0 });
  }
}

// --- Counts ---
const counts = {
  totalProjects: projects.length, activeProjects: activeProjects.length,
  totalTasks: allTasks.length, openTasks: openTasks.length,
  googleTotal: google.length, notionTotal: notionTasks.length,
  overdue: overdue.length, dueToday: dueToday.length, dueSoon: dueSoon.length,
  duplicatesHigh: matches.filter(m => m.conf === 'high').length,
  duplicatesPossible: matches.filter(m => m.conf === 'possible').length,
  unassigned: unassigned.filter(t => t.projInferred.length === 0).length,
  suggestedLinks: unassigned.filter(t => t.projInferred.length > 0).length,
  diffNew: diff.newTasks.length, diffCompleted: diff.completedTasks.length,
};

return [{
  json: {
    isoDate, tz: TZ, counts, projects, openTasks, overdue, dueToday, dueSoon,
    matches, unassigned: unassigned.filter(t => t.projInferred.length > 0),
    projView, diff, yesterdayDate: yesterday.date,
    sourceHealth: { notion: notionTasks.length > 0 ? 'ok' : 'empty', google: google.length > 0 ? 'ok' : 'empty', projects: notionProjects.length > 0 ? 'ok' : 'empty' }
  }
}];

// === Build LLM Prompt for Executive Summary ===
const d = $json;
const counts = d.counts;
const overdue = d.overdue || [];
const dueToday = d.dueToday || [];
const dueSoon = d.dueSoon || [];
const matches = d.matches || [];
const unassigned = d.unassigned || [];
const diff = d.diff || {};
const projView = d.projView || {};

function safeStr(x, max = 100) {
    const s = (x ?? '').toString().replace(/\s+/g, ' ').trim();
    return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

// Build compact tables for LLM context
let ctx = '';
ctx += `Date: ${d.isoDate} (${d.tz})\n`;
ctx += `Open tasks: ${counts.openTasks} | Overdue: ${counts.overdue} | Due today: ${counts.dueToday} | Due soon (7d): ${counts.dueSoon}\n`;
ctx += `Projects: ${counts.activeProjects} active | Duplicates: ${counts.duplicatesHigh} high, ${counts.duplicatesPossible} possible\n`;
ctx += `Changes since ${d.yesterdayDate || 'N/A'}: ${counts.diffNew} new, ${counts.diffCompleted} completed\n\n`;

if (overdue.length) {
    ctx += `OVERDUE TASKS:\n`;
    overdue.slice(0, 15).forEach(t => { ctx += `- [${t.src}] ${safeStr(t.title, 80)} (due: ${t.due})\n`; });
    ctx += '\n';
}
if (dueToday.length) {
    ctx += `DUE TODAY:\n`;
    dueToday.slice(0, 10).forEach(t => { ctx += `- [${t.src}] ${safeStr(t.title, 80)}\n`; });
    ctx += '\n';
}
if (dueSoon.length) {
    ctx += `DUE SOON (next 7 days):\n`;
    dueSoon.slice(0, 15).forEach(t => { ctx += `- [${t.src}] ${safeStr(t.title, 80)} (due: ${t.due})\n`; });
    ctx += '\n';
}

const projKeys = Object.keys(projView);
if (projKeys.length) {
    ctx += `PROJECTS WITH OPEN TASKS:\n`;
    projKeys.slice(0, 10).forEach(k => {
        const pv = projView[k];
        ctx += `  ${pv.title}: ${pv.tasks.length} tasks\n`;
        pv.tasks.slice(0, 5).forEach(t => { ctx += `    - ${safeStr(t.title, 60)} ${t.due ? '(due:' + t.due + ')' : ''} ${t.inferred ? '[INFERRED LINK]' : ''}\n`; });
    });
    ctx += '\n';
}

if (matches.length) {
    ctx += `POTENTIAL DUPLICATES:\n`;
    matches.slice(0, 10).forEach(m => {
        ctx += `- [${m.conf}] "${safeStr(m.aTitle, 50)}" ↔ "${safeStr(m.bTitle, 50)}" (score: ${m.score}, ${m.type})\n`;
    });
    ctx += '\n';
}

const prompt = `You are a productivity advisor. You MUST respond with ONLY valid JSON, no other text.\n\nINPUT DATA:\n${ctx}\n\nRespond with ONLY this JSON structure (no markdown, no explanations):\n{\n  "executiveSummary": ["brief point 1", "brief point 2"],\n  "topPriorities": [\n    {"title":"task name","reason":"why urgent","estimatedMinutes":30,"urgency":"high"}\n  ],\n  "projectRisks": [\n    {"project":"project name","risk":"what's wrong","suggestion":"how to fix"}\n  ],\n  "suggestedActions": ["action 1", "action 2"],\n  "notes": ["any other notes"]\n}`;

return [{ json: { ...d, llmPrompt: prompt } }];

// === Robust LLM JSON Parser ===
function extractFirstJsonObject(text) {
    if (!text) return null;
    const s = String(text);
    const firstBrace = s.indexOf('{');
    if (firstBrace === -1) return null;
    let depth = 0, inStr = false, esc = false;
    for (let i = firstBrace; i < s.length; i++) {
        const ch = s[i];
        if (inStr) {
            if (esc) { esc = false; continue; }
            if (ch === '\\') { esc = true; continue; }
            if (ch === '"') { inStr = false; continue; }
            continue;
        } else {
            if (ch === '"') { inStr = true; continue; }
            if (ch === '{') depth++;
            if (ch === '}') depth--;
            if (depth === 0) return s.slice(firstBrace, i + 1);
        }
    }
    return null;
}

const raw = $json?.response ?? $json?.text ?? $json?.content ?? $json?.message ?? ($json?.data ? JSON.stringify($json.data) : null) ?? JSON.stringify($json);

let parsed = null, parseError = null;
try { parsed = JSON.parse(raw); } catch (e1) {
    try {
        const candidate = extractFirstJsonObject(raw);
        if (!candidate) throw new Error('No JSON object found in LLM output');
        parsed = JSON.parse(candidate);
    } catch (e2) { parseError = e2.message; }
}

// Pass through all upstream data
const upstream = $('Build LLM Prompt1').first()?.json || {};
return [{ json: { ...upstream, llmRaw: String(raw), llmParsed: parsed, llmParseOk: !!parsed, llmParseError: parseError } }];

// === Build Morning Brief Email (HTML + plain text) ===
const d = $json;
const openTasks = d.openTasks || [];
const counts = d.counts || {};
const overdue = d.overdue || [];
const dueToday = d.dueToday || [];
const dueSoon = d.dueSoon || [];
const matches = d.matches || [];
const unassigned = d.unassigned || [];
const projView = d.projView || {};
const diff = d.diff || {};
const ok = d.llmParseOk;
const llm = d.llmParsed || {};
const isoDate = d.isoDate;
const tz = d.tz || 'Europe/Dublin';
const sourceHealth = d.sourceHealth || {};

function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function safeStr(x, max = 100) { const s = (x ?? '').toString().replace(/\s+/g, ' ').trim(); return s.length > max ? s.slice(0, max - 1) + '…' : s; }
function normTitle(s) { return String(s ?? '').toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim(); }

// Build URL lookup map from openTasks by normalized title
const taskUrlMap = {};
for (const t of openTasks) {
    if (t.url) taskUrlMap[normTitle(t.title)] = t.url;
}

// LLM data with fallbacks
const execSummary = ok && Array.isArray(llm.executiveSummary) ? llm.executiveSummary : [`${counts.openTasks || 0} open tasks. ${counts.overdue || 0} overdue.`];
const topPriorities = ok && Array.isArray(llm.topPriorities) ? llm.topPriorities : overdue.slice(0, 5).map(t => ({ title: t.title, reason: 'Overdue', estimatedMinutes: null, urgency: 'high' }));
const projectRisks = ok && Array.isArray(llm.projectRisks) ? llm.projectRisks : [];
const suggestedActions = ok && Array.isArray(llm.suggestedActions) ? llm.suggestedActions : [];
const notes = ok && Array.isArray(llm.notes) ? llm.notes : [];
if (!ok) notes.unshift('LLM output could not be parsed: ' + (d.llmParseError || 'unknown error'));

const subject = `Morning Brief — ${isoDate} (open: ${counts.openTasks || 0}, overdue: ${counts.overdue || 0})`;

// ===================== PLAIN TEXT =====================
let text = '';
text += `Morning Brief — ${isoDate} (${tz})\n${'='.repeat(52)}\n\n`;

text += `EXECUTIVE SUMMARY\n`;
execSummary.forEach(b => { text += `• ${b}\n`; }); text += '\n';

text += `DASHBOARD: Open ${counts.openTasks || 0} | Overdue ${counts.overdue || 0} | Due today ${counts.dueToday || 0} | Due soon ${counts.dueSoon || 0}\n`;
text += `Projects: ${counts.activeProjects || 0} active | Duplicates: ${counts.duplicatesHigh || 0} high, ${counts.duplicatesPossible || 0} possible\n`;
text += `Changes since ${d.yesterdayDate || 'N/A'}: +${counts.diffNew || 0} new, ✓${counts.diffCompleted || 0} completed\n\n`;

if (topPriorities.length) {
    text += `PROJECT TOP PRIORITIES\n`;
    topPriorities.forEach((t, i) => {
        const tUrl = taskUrlMap[normTitle(t.title)] || '';
        text += `${i + 1}. ${t.title} [${t.urgency || ''}] ~${t.estimatedMinutes || '?'}min${tUrl ? ' ' + tUrl : ''}\n`;
        if (t.reason) text += `   ${t.reason}\n`;
    }); text += '\n';
}

if (overdue.length) {
    text += `OVERDUE (${overdue.length})\n`;
    overdue.forEach(t => { text += `- ${t.title} [${t.src}] due: ${t.due}\n`; }); text += '\n';
}

const projKeys = Object.keys(projView);
if (projKeys.length) {
    text += `PROJECT VIEW\n`;
    projKeys.forEach(k => {
        const pv = projView[k];
        text += `  ${pv.title} (${pv.tasks.length} tasks)\n`;
        pv.tasks.slice(0, 5).forEach(t => { text += `    - ${t.title}${t.due ? ' due:' + t.due : ''}${t.inferred ? ' [inferred]' : ''}\n`; });
    }); text += '\n';
}

if (unassigned.length) {
    text += `UNASSIGNED TASKS WITH SUGGESTED PROJECTS\n`;
    unassigned.forEach(t => {
        text += `- ${t.title} → suggestion: ${t.projInferred.map(p => p.title + '(' + p.score + ')').join(', ')}\n`;
    }); text += '\n';
}

if (matches.length) {
    text += `POTENTIAL DUPLICATES\n`;
    matches.forEach(m => { text += `- [${m.conf}] "${m.aTitle}" ↔ "${m.bTitle}" (score:${m.score}, ${m.type})\n`; });
    text += '\n';
}

const diffNew = diff.newTasks || []; const diffDone = diff.completedTasks || [];
const diffDue = diff.dueChanges || []; const diffRem = diff.removedTasks || [];
if (diffNew.length || diffDone.length || diffDue.length || diffRem.length) {
    text += `CHANGES SINCE ${d.yesterdayDate || 'YESTERDAY'}\n`;
    diffNew.forEach(t => { text += `  + NEW: ${t.title} [${t.src}]\n`; });
    diffDone.forEach(t => { text += `  ✓ DONE: ${t.title} [${t.src}]\n`; });
    diffDue.forEach(t => { text += `  ⇄ DUE CHANGED: ${t.title} (${t.oldDue} → ${t.newDue})\n`; });
    diffRem.forEach(t => { text += `  - REMOVED: ${t.title}\n`; });
    text += '\n';
}

if (suggestedActions.length) {
    text += `SUGGESTED ACTIONS\n`;
    suggestedActions.forEach(a => { text += `☐ ${a}\n`; }); text += '\n';
}

// Machine-readable appendix
const appendix = JSON.stringify({ run_id: isoDate, timezone: tz, counts, duplicates: { high: counts.duplicatesHigh, possible: counts.duplicatesPossible }, missing_links: counts.suggestedLinks, source_health: sourceHealth });
text += `---\nMACHINE-READABLE: ${appendix}\n`;

// ===================== HTML =====================
function chip(label, bg = '#1f2a44') {
    return `<span style="display:inline-block;padding:2px 10px;border-radius:999px;background:${bg};border:1px solid #2a3a64;color:#e8eefc;font-size:12px;line-height:18px;">${esc(label)}</span>`;
}
function metricCard(label, value, accent = '#e8eefc') {
    return `<td style="padding:6px;vertical-align:top;"><div style="background:#111827;border:1px solid #223055;border-radius:14px;padding:12px;"><div style="color:#9fb0d0;font-size:12px;letter-spacing:.2px;">${esc(label)}</div><div style="color:${accent};font-size:20px;font-weight:700;margin-top:6px;">${esc(String(value))}</div></div></td>`;
}
function section(title, content) {
    return `<div style="margin-top:18px;"><div style="font-size:16px;font-weight:900;color:#e8eefc;margin-bottom:8px;">${esc(title)}</div>${content}</div>`;
}
function taskRow(t, extra = '') {
    const due = t.due ? chip(`Due ${esc(t.due)}`) : '';
    const src = chip(t.src || '');
    const urlBtn = t.url ? ` <a href="${esc(t.url)}" style="color:#60a5fa;font-size:12px;text-decoration:none;">Open →</a>` : '';
    return `<div style="background:#0f172a;border:1px solid #223055;border-radius:12px;padding:10px 12px;margin-top:6px;"><div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">${src} ${due} ${extra}</div><div style="color:#e8eefc;font-size:14px;font-weight:700;margin-top:6px;">${esc(safeStr(t.title, 80))}${urlBtn}</div></div>`;
}

// Source health banner
let healthBanner = '';
const unhealthy = Object.entries(sourceHealth).filter(([, v]) => v !== 'ok');
if (unhealthy.length) {
    healthBanner = `<div style="background:#3a1f20;border:1px solid #6b2020;border-radius:14px;padding:12px 14px;margin-top:12px;color:#fca5a5;font-weight:700;">⚠ Source issues: ${unhealthy.map(([k, v]) => esc(k) + ': ' + esc(v)).join(', ')}</div>`;
}

let html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Morning Brief</title></head>`;
html += `<body style="margin:0;padding:0;background:#0b1020;color:#e8eefc;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;">`;
html += `<div style="display:none;max-height:0;overflow:hidden;opacity:0;">Morning Brief — ${esc(isoDate)}</div>`;
html += `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;background:#0b1020;"><tr><td align="center" style="padding:22px 10px;">`;
html += `<table role="presentation" width="640" cellspacing="0" cellpadding="0" style="border-collapse:collapse;max-width:640px;width:100%;"><tr><td style="background:#0f172a;border:1px solid #223055;border-radius:18px;padding:18px;">`;

// Header
html += `<div style="font-size:12px;color:#9fb0d0;letter-spacing:.2px;">Morning Brief</div>`;
html += `<div style="font-size:22px;font-weight:900;color:#e8eefc;margin-top:6px;">Your tasks for today</div>`;
html += `<div style="font-size:13px;color:#9fb0d0;margin-top:6px;">${esc(isoDate)} · ${esc(tz)}</div>`;
html += healthBanner;

// Executive summary
if (execSummary.length) {
    html += section('Executive Summary', `<ul style="margin:4px 0 0 18px;padding:0;color:#c8d4f0;">${execSummary.map(b => `<li style="margin:4px 0;line-height:18px;">${esc(b)}</li>`).join('')}</ul>`);
}

// Metric cards
html += `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;margin-top:14px;">`;
html += `<tr>${metricCard('Open tasks', counts.openTasks || 0)}${metricCard('Overdue', counts.overdue || 0, '#fca5a5')}</tr>`;
html += `<tr>${metricCard('Due today', counts.dueToday || 0, '#fbbf24')}${metricCard('Due soon (7d)', counts.dueSoon || 0)}</tr>`;
html += `<tr>${metricCard('Duplicates (high)', counts.duplicatesHigh || 0)}${metricCard('Suggested links', counts.suggestedLinks || 0)}</tr>`;
html += `</table>`;

// Top priorities
if (topPriorities.length) {
    let pHtml = '';
    topPriorities.forEach((t, i) => {
        const urgColor = t.urgency === 'critical' ? '#ef4444' : t.urgency === 'high' ? '#f59e0b' : '#60a5fa';
        const tUrl = taskUrlMap[normTitle(t.title)] || '';
        const urlBtn = tUrl ? ` <a href="${esc(tUrl)}" style="color:#60a5fa;font-size:12px;text-decoration:none;">Open →</a>` : '';
        pHtml += `<div style="background:#0f172a;border:1px solid #223055;border-radius:12px;padding:10px 12px;margin-top:6px;">`;
        pHtml += `<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">${chip('#' + (i + 1))} ${chip(t.urgency || 'medium', urgColor + '33')} ${t.estimatedMinutes ? chip('~' + t.estimatedMinutes + 'min') : ''}</div>`;
        pHtml += `<div style="color:#e8eefc;font-size:14px;font-weight:700;margin-top:6px;">${esc(safeStr(t.title, 80))}${urlBtn}</div>`;
        if (t.reason) pHtml += `<div style="color:#9fb0d0;font-size:12px;margin-top:4px;">${esc(t.reason)}</div>`;
        pHtml += `</div>`;
    });
    html += section('Project Top Priorities', pHtml);
}

// Overdue
if (overdue.length) {
    html += section(`Overdue (${overdue.length})`, overdue.slice(0, 10).map(t => taskRow(t, chip('OVERDUE', '#7f1d1d'))).join(''));
}

// Due today
if (dueToday.length) {
    html += section(`Due Today (${dueToday.length})`, dueToday.map(t => taskRow(t)).join(''));
}

// Due soon
if (dueSoon.length) {
    html += section(`Due Soon — next 7 days (${dueSoon.length})`, dueSoon.slice(0, 10).map(t => taskRow(t)).join(''));
}

// Project view
if (projKeys.length) {
    let pvHtml = '';
    projKeys.forEach(k => {
        const pv = projView[k];
        pvHtml += `<div style="background:#111827;border:1px solid #223055;border-radius:14px;padding:12px;margin-top:8px;">`;
        pvHtml += `<div style="color:#e8eefc;font-weight:800;font-size:14px;">${esc(pv.title)} <span style="color:#9fb0d0;font-weight:400;">(${pv.tasks.length} tasks)</span></div>`;
        pv.tasks.slice(0, 5).forEach(t => {
            pvHtml += `<div style="color:#c8d4f0;font-size:13px;margin-top:4px;padding-left:8px;">• ${esc(safeStr(t.title, 70))}${t.due ? ' <span style="color:#9fb0d0;">due ' + esc(t.due) + '</span>' : ''}${t.inferred ? ' ' + chip('inferred', '#1e3a5f') : ''}</div>`;
        });
        pvHtml += `</div>`;
    });
    html += section('Project View', pvHtml);
}

// Unassigned with suggestions
if (unassigned.length) {
    let uHtml = '';
    unassigned.forEach(t => {
        uHtml += `<div style="background:#0f172a;border:1px solid #223055;border-radius:12px;padding:10px 12px;margin-top:6px;">`;
        uHtml += `<div style="color:#e8eefc;font-size:14px;font-weight:700;">${esc(safeStr(t.title, 80))}</div>`;
        uHtml += `<div style="color:#9fb0d0;font-size:12px;margin-top:4px;">Suggested: ${t.projInferred.map(p => esc(p.title) + ' (' + p.score + ')').join(', ')}</div>`;
        uHtml += `</div>`;
    });
    html += section('Unassigned Tasks — Suggested Projects', uHtml);
}

// Duplicates
if (matches.length) {
    const highDups = matches.filter(m => m.conf === 'high');
    const possibleDups = matches.filter(m => m.conf === 'possible');
    let dupHtml = '';
    const renderDup = (m) => {
        const badge = m.conf === 'high' ? chip('HIGH', '#7f1d1d') : chip(m.conf, '#1f2a44');
        return `<div style="background:#0f172a;border:1px solid #223055;border-radius:12px;padding:10px 12px;margin-top:6px;"><div>${badge} ${chip(m.type)} ${chip('score: ' + m.score)}</div><div style="color:#e8eefc;font-size:13px;margin-top:6px;">"${esc(safeStr(m.aTitle, 60))}" ↔ "${esc(safeStr(m.bTitle, 60))}"</div><div style="color:#9fb0d0;font-size:11px;margin-top:2px;">${m.rationale.map(r => esc(r)).join(' · ')}</div></div>`;
    };
    if (highDups.length) dupHtml += highDups.map(renderDup).join('');
    if (possibleDups.length) dupHtml += possibleDups.map(renderDup).join('');
    html += section(`Potential Duplicates (${matches.length})`, dupHtml);
}

// Changes since yesterday
if (diffNew.length || diffDone.length || diffDue.length || diffRem.length) {
    let chHtml = '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">';
    const row = (icon, label, color) => `<tr><td style="padding:4px 8px;border-bottom:1px solid #223055;color:${color};font-size:13px;"><span style="font-size:16px;">${icon}</span> ${esc(label)}</td></tr>`;
    diffNew.forEach(t => { chHtml += row('✚', `NEW: ${safeStr(t.title, 70)} [${t.src}]`, '#34d399'); });
    diffDone.forEach(t => { chHtml += row('✓', `DONE: ${safeStr(t.title, 70)} [${t.src}]`, '#60a5fa'); });
    diffDue.forEach(t => { chHtml += row('⇄', `DUE: ${safeStr(t.title, 50)} (${t.oldDue} → ${t.newDue})`, '#fbbf24'); });
    diffRem.forEach(t => { chHtml += row('−', `REMOVED: ${safeStr(t.title, 70)}`, '#9fb0d0'); });
    chHtml += '</table>';
    html += section(`Changes since ${esc(d.yesterdayDate || 'yesterday')}`, chHtml);
}

// Suggested actions
if (suggestedActions.length) {
    html += section('Suggested Actions', `<ul style="margin:4px 0 0 18px;padding:0;color:#c8d4f0;">${suggestedActions.map(a => `<li style="margin:4px 0;line-height:18px;">${esc(a)}</li>`).join('')}</ul>`);
}

// Notes
if (notes.length) {
    html += `<div style="margin-top:16px;background:#0f172a;border:1px solid #223055;border-radius:16px;padding:12px 14px;"><div style="color:#e8eefc;font-weight:800;">Notes</div><ul style="margin:8px 0 0 18px;color:#c8d4f0;padding:0;">${notes.map(n => `<li style="margin:6px 0;line-height:18px;">${esc(n)}</li>`).join('')}</ul></div>`;
}

// Machine-readable appendix
html += `<details style="margin-top:14px;"><summary style="color:#6f86b3;font-size:12px;cursor:pointer;">Machine-readable appendix</summary><pre style="color:#6f86b3;font-size:10px;white-space:pre-wrap;margin-top:4px;">${esc(appendix)}</pre></details>`;

// Footer
html += `<div style="margin-top:16px;color:#6f86b3;font-size:12px;">Generated at: ${esc(new Date().toISOString())}</div>`;
if (!ok) {
    html += `<div style="margin-top:14px;background:#1a1020;border:1px solid #3a1f55;border-radius:16px;padding:12px 14px;"><div style="color:#f5d0fe;font-weight:800;">LLM parse error</div><div style="color:#f1c3ff;font-size:12px;margin-top:6px;white-space:pre-wrap;">${esc(String(d.llmRaw || '').slice(0, 500))}</div></div>`;
}

html += `</td></tr><tr><td style="padding:12px 4px;text-align:center;color:#536a99;font-size:11px;">Sent automatically via n8n · Morning Brief Advisor</td></tr></table></td></tr></table></body></html>`;

return [{ json: { to: 'YOUR_EMAIL@EXAMPLE.COM', subject, text, html } }];
